import type { Question, StudyModule } from "../module-types";

// ETH-01 Codes of Ethics
const lessons1=[
{title:"The fundamental canons",body:"Engineering codes of ethics (modeled on the NSPE Code) rest on a small set of fundamental canons: (1) hold paramount the safety, health, and welfare of the public; (2) perform services only in areas of your competence; (3) issue public statements only in an objective and truthful manner; (4) act for each employer or client as a faithful agent or trustee, avoiding conflicts of interest; (5) avoid deceptive acts and build your reputation on the merit of your services; and (6) conduct yourself honorably, responsibly, ethically, and legally. When canons appear to conflict, canon 1 — protecting the public — always controls."},
{title:"Conflicts of interest and gifts",body:"Engineers must disclose all known or potential conflicts of interest to their employers or clients before accepting an assignment, and must not accept compensation from more than one party for services on the same project unless all interested parties consent after full disclosure. This extends to gifts, commissions, or favors from contractors, vendors, or bidders — anything that could reasonably be seen as influencing professional judgment should be declined, not merely managed after the fact."},
{title:"Competence and sealing engineering work",body:"A licensed engineer may offer services and sign or seal documents only in disciplines for which they are qualified by education and experience. Sealing requires that the engineer personally prepared the work or exercised direct supervisory control and review over its preparation. Sealing someone else's unreviewed work — sometimes called 'plan-stamping' — is a serious ethics and licensure violation, regardless of who requested it or how routine the request seemed."},
{title:"Honesty, objectivity, and public statements",body:"Engineers must issue public statements, expert testimony, and marketing or promotional materials in an objective and truthful manner, disclosing when they speak on behalf of an interested party. They must give proper credit for engineering work to those actually responsible, and must not misrepresent their qualifications, falsify credentials, or overstate the certainty of their results — this obligation applies to marketing materials just as much as to technical reports."}
];

const flashcards1=[
{front:"Canon 1 (paramount duty)",back:"Hold paramount the safety, health, and welfare of the public",note:"This canon outranks all others, including loyalty to a client or employer."},
{front:"Faithful agent/trustee",back:"Act for each employer or client as a faithful agent, avoiding conflicts of interest",note:"The faithful-agent duty always yields to the paramount public-safety duty."},
{front:"Area of competence",back:"Perform services only in areas of your training and experience",note:"If a task exceeds your competence, decline it or bring in a qualified specialist."},
{front:"Sealing engineering work",back:"Seal only work you personally prepared or directly supervised and reviewed",note:"Sealing unreviewed third-party work ('plan-stamping') is a licensure violation."},
{front:"Conflict of interest disclosure",back:"Disclose all known or potential conflicts of interest before accepting an assignment",note:"Disclosure, not silence, is what makes a conflict manageable."},
{front:"Gifts and dual compensation",back:"Do not accept compensation from more than one party for the same service without consent of all parties",note:"Applies to gifts, commissions, and finder's fees from vendors/contractors too."},
{front:"Objective public statements",back:"Issue public statements, testimony, and marketing claims only in an objective and truthful manner",note:"Disclose interest/sponsorship whenever you speak on behalf of an interested party."}
];

const questions1:Question[]=[
{id:"ETH01-Q01",skill:"Competence and sealing",difficulty:"Easy",prompt:"A structural engineer is asked to review and seal HVAC ductwork drawings because the firm's only mechanical engineer is on leave. She has no HVAC design background or training. What should she do?",choices:["Seal the drawings anyway since the deadline is tight and the firm needs the work done.","Decline to seal the drawings and refer the work to a qualified mechanical/HVAC engineer.","Seal the drawings but add a note disclaiming responsibility for the HVAC content.","Ask a junior drafter without a PE license to review and approve the drawings instead."],answer:1,explanation:"She should decline to seal work outside her area of competence and refer it to a qualified engineer.",solution:"Step 1 — Identify the governing principle: engineers must practice and seal work only within their area of competence.\nStep 2 — Apply it to the facts: HVAC design is outside this engineer's training and experience.\nStep 3 — Evaluate the options: sealing regardless of competence, or with a disclaimer, does not cure the underlying competence gap; delegating review to an unlicensed drafter does not satisfy sealing requirements either.\nStep 4 — The only option consistent with the competence canon is declining and referring the work to a qualified mechanical/HVAC engineer.\nFinal answer: Decline to seal and refer the drawings to a qualified engineer.",trap:"Adding a disclaimer (choice C) is a common trap — a disclaimer does not change the fact that sealing represents a claim of competence and responsibility that isn't true here.",repair:"If a task is outside your area of competence, decline or route it to a qualified engineer — a disclaimer cannot substitute for actual competence."},
{id:"ETH01-Q02",skill:"Conflicts of interest and gifts",difficulty:"Easy",prompt:"A general contractor bidding on a project offers an engineer tickets to a major sporting event while the engineer is currently evaluating competing bids for a client. What is the correct action?",choices:["Accept the tickets, since they are a personal gift unrelated to the contract price.","Accept the tickets, then recuse from evaluating that contractor's bid.","Decline the gift and disclose the offer to the client, consistent with conflict-of-interest obligations.","Accept the tickets only if their value is below the firm's internal gift threshold."],answer:2,explanation:"Gifts from a party with a pending interest in the engineer's decision should be declined and disclosed, not accepted.",solution:"Step 1 — Identify the principle: engineers must avoid conflicts of interest and must not accept gifts/gratuities that could reasonably influence professional judgment.\nStep 2 — Apply it: the contractor has a direct pending interest in the bid evaluation the engineer is performing.\nStep 3 — Accepting first and recusing afterward still means an improper gift was accepted and creates an appearance of impropriety.\nStep 4 — The correct action is to decline the gift outright and disclose the offer.\nFinal answer: Decline the gift and disclose the offer to the client.",trap:"Accepting and then recusing (choice B) still leaves an improper gift accepted and an appearance of favoritism — recusal after the fact doesn't undo it.",repair:"Decline gifts or hospitality from any party with a pending interest in your professional decisions, and disclose the offer."},
{id:"ETH01-Q03",skill:"Paramount public safety",difficulty:"Medium",prompt:"During design development, a client instructs the engineer of record to reduce a structural safety margin below the applicable building code's minimum requirement in order to cut costs, insisting this is purely a business decision. What should the engineer do?",choices:["Comply, since the engineer acts as the client's faithful agent.","Comply, but document in the project file that the client directed the reduction.","Refuse to design below the code-required minimum, since protecting public safety is paramount and cannot be waived by client instruction.","Resign from the project immediately without discussing the code issue with the client."],answer:2,explanation:"The paramount duty to public safety overrides a client's business instruction to go below a code-mandated safety minimum.",solution:"Step 1 — Identify the governing principle: Canon 1 — hold paramount the safety, health, and welfare of the public — outranks the faithful-agent duty to a client.\nStep 2 — Apply it: a code-minimum safety margin exists specifically to protect public safety; going below it is not a discretionary business choice.\nStep 3 — Documenting noncompliance (choice B) does not make noncompliance acceptable — it only creates a paper trail of the same violation.\nStep 4 — The correct action is to refuse to design below the code minimum.\nFinal answer: Refuse to design below the code-required minimum.",trap:"Documenting the client's instruction (choice B) feels like professional diligence, but it does not fix the underlying violation — the design still fails to meet the code-required safety minimum.",repair:"When a client's wishes conflict with a code-mandated public-safety requirement, the code requirement controls — documentation of noncompliance is not a substitute for compliance."},
{id:"ETH01-Q04",skill:"Deceptive acts and reporting",difficulty:"Medium",prompt:"An engineer discovers that a colleague falsified soil-bearing test data before it was submitted in a geotechnical report used for a foundation design, and the project is already under construction. What is the correct first step?",choices:["Say nothing, since the engineer did not personally falsify the data.","Raise the issue internally with the responsible engineer and firm management to correct and re-evaluate the false data, escalating to the licensing board or building authority if it is not promptly addressed.","Report the colleague directly to a news outlet before contacting anyone at the firm.","Quietly redo the calculations with corrected data without telling anyone."],answer:1,explanation:"The correct response is to raise the issue internally first and escalate to the appropriate authority if it isn't corrected, given the ongoing safety risk.",solution:"Step 1 — Identify the principle: engineers must not tolerate deceptive acts, and public safety is paramount, especially where construction is already proceeding on falsified data.\nStep 2 — Apply it: the appropriate path is to raise the concern through internal/firm channels first so the false data can be corrected and re-evaluated.\nStep 3 — If the concern is not addressed given the urgency, escalate to the licensing board or building official.\nStep 4 — Going straight to the media (choice C) bypasses the proper escalation channels without exhausting them first.\nFinal answer: Raise it internally, escalating to the appropriate authority if unresolved.",trap:"Going straight to the media (choice C) feels decisive given the safety stakes, but it skips the proper internal-then-authority escalation sequence and is not a standard professional channel for correcting the data.",repair:"Escalate safety-relevant concerns first internally, then to the client/owner, then to the appropriate public authority if unresolved — match the speed of escalation to the urgency of the risk."},
{id:"ETH01-Q05",skill:"Competence and sealing",difficulty:"Medium",prompt:"A licensed PE directly supervises and reviews the calculations a junior engineer performed for a project, taking responsibility for the final design before applying her seal. Is this an ethical use of the PE seal?",choices:["No — only the engineer who personally performed 100% of the calculations may ethically seal the work.","Yes — because the PE exercised direct supervisory control and reviewed and takes responsibility for the work before sealing it.","No — sealing requires that no assistance of any kind be used in preparing the work.","Yes — but only if the junior engineer is also listed as a co-signer alongside the PE's seal."],answer:1,explanation:"Sealing is ethical when the PE directly supervised, reviewed, and takes responsibility for the work, even if others helped prepare it.",solution:"Step 1 — Identify the principle: a PE may seal work they personally prepared or that was prepared under their direct supervisory control and review.\nStep 2 — Apply it: the PE reviewed the junior engineer's calculations and took responsibility before sealing — this satisfies the supervisory-control standard.\nStep 3 — Requiring the sealing engineer to have done 100% of the work personally (choice A) is stricter than the actual standard.\nFinal answer: Yes — direct supervisory control and review before sealing is the ethical standard.",trap:"Choice A sounds like the safest, strictest answer, but it misstates the actual rule — supervision and review, not sole authorship, is what the codes require for sealing.",repair:"A PE may ethically seal work performed by others under their direct supervision and review — sealing does not require having personally done every calculation."},
{id:"ETH01-Q06",skill:"Conflicts of interest and gifts",difficulty:"Hard",prompt:"An engineer is retained as a paid consultant by two different companies that are competing for the same municipal contract, without informing either company of the dual engagement. Is this a violation, and why?",choices:["No violation, because the technical advice given to each client is accurate and independently developed.","Yes — this is an undisclosed conflict of interest, because the engineer's loyalty and judgment could be compromised, or reasonably appear compromised, without both clients' knowledge and consent.","No violation, because consulting engineers may work for any number of clients simultaneously without restriction.","Yes, but only because the engineer is being paid, not because of the conflicting interests themselves."],answer:1,explanation:"The violation is the undisclosed conflicting loyalty itself, not whether the technical advice given happened to be accurate.",solution:"Step 1 — Identify the principle: engineers must disclose all known or potential conflicts of interest before accepting an assignment.\nStep 2 — Apply it: engaging with two direct competitors for the same contract, without disclosure, creates a conflicting-loyalty situation regardless of the quality of advice given.\nStep 3 — Technical accuracy (choice A) addresses competence, not disclosure — it does not resolve the conflict-of-interest violation.\nFinal answer: Yes, this is an undisclosed conflict of interest.",trap:"Choice A conflates 'the work was technically correct' with 'there was no conflict of interest' — these are separate ethical questions, and accuracy of output does not cure a failure to disclose competing loyalties.",repair:"A conflict of interest is defined by undisclosed competing loyalties, not by whether the resulting technical work happens to be accurate."},
{id:"ETH01-Q07",skill:"Honesty and public statements",difficulty:"Easy",prompt:"An engineering firm's marketing brochure states that its lead engineer has '20 years of nuclear plant design experience,' when she actually has 20 years of general mechanical design experience with only 2 years in nuclear-related work. What ethical principle does this best violate?",choices:["No violation, since marketing materials are not held to the same standard as technical reports.","A violation of the duty to issue objective and truthful public statements and not misrepresent qualifications.","No violation, since general mechanical experience is broadly transferable to nuclear work.","A violation, but only if the misstatement affects the firm's fee for the project."],answer:1,explanation:"Truthful representation of qualifications is required in public/marketing statements, not just technical documents.",solution:"Step 1 — Identify the principle: engineers must issue public statements, including marketing materials, in an objective and truthful manner and must not misrepresent qualifications.\nStep 2 — Apply it: stating '20 years of nuclear experience' when only 2 years is accurate materially misrepresents her qualifications.\nStep 3 — This obligation is not limited to technical reports (choice A) — it explicitly covers public and marketing statements.\nFinal answer: A violation of the duty to make truthful, objective public statements about qualifications.",trap:"Choice A assumes marketing materials get a lower standard of honesty than technical reports — the codes of ethics apply the truthfulness requirement broadly to all public statements.",repair:"Truthfulness and accurate representation of qualifications apply to marketing and public statements, not just technical reports."},
{id:"ETH01-Q08",skill:"Competence and sealing",difficulty:"Medium",prompt:"An employer directs a PE to sign and seal a set of structural calculations for a project she has never reviewed, explaining that 'the numbers were double-checked by someone else.' What should the PE do?",choices:["Sign and seal the calculations, trusting the employer's assurance that they were checked.","Decline to seal the calculations unless she personally reviews them or has exercised the direct supervisory control required to take professional responsibility for them.","Sign the calculations, but have the other reviewer also co-sign them.","Delegate the decision of whether to seal to the employer's legal department."],answer:1,explanation:"A seal represents the sealing engineer's own review and responsibility; an unverified assurance from someone else does not satisfy that requirement.",solution:"Step 1 — Identify the principle: sealing requires personal preparation or direct supervisory control and review by the sealing engineer.\nStep 2 — Apply it: relying solely on an unverified assurance that 'someone else' checked the numbers does not meet that standard.\nStep 3 — Co-signing (choice C) or delegating the decision (choice D) does not substitute for the PE's own required review before applying her seal.\nFinal answer: Decline to seal unless she personally reviews or has directly supervised the work.",trap:"Trusting the employer's assurance (choice A) feels reasonable in a busy workplace, but the seal is a personal professional certification — it cannot rest on an unverified secondhand claim.",repair:"Never seal work based solely on someone else's assurance — you must personally review it or have directly supervised its preparation."},
{id:"ETH01-Q09",skill:"Conflicts of interest and gifts",difficulty:"Hard",prompt:"An engineer sits on a municipal planning board that must vote on approving a development project designed by her own firm. What is the ethically correct course of action?",choices:["Vote based purely on technical merit, since her professional judgment on the design is sound regardless of the firm relationship.","Disclose the conflict of interest to the board and recuse herself from discussing and voting on that specific project.","Vote against the project regardless of merit, to avoid any appearance of favoritism toward her firm.","Abstain from voting on the project, without stating the reason to the board."],answer:1,explanation:"A conflict of interest requires both disclosure and recusal, not just silent non-participation.",solution:"Step 1 — Identify the principle: engineers must disclose all known or potential conflicts of interest.\nStep 2 — Apply it: reviewing/voting on her own firm's project is a direct conflict requiring disclosure to the board.\nStep 3 — After disclosure, the appropriate action is recusal from discussion and voting on that specific matter.\nStep 4 — Abstaining without disclosure (choice D) hides the reason for non-participation from the board and public.\nFinal answer: Disclose the conflict and recuse from that project's discussion and vote.",trap:"Silently abstaining (choice D) might seem like a safe, low-key solution, but without disclosure the board and public never learn why she stepped back — transparency is the essential part of managing the conflict.",repair:"A conflict of interest requires both disclosure and recusal — silently abstaining is not sufficient."},
{id:"ETH01-Q10",skill:"Competence and sealing",difficulty:"Hard",prompt:"An engineer is asked to design a component using a specialized composite-materials analysis method she has not used before. She studies the method extensively and has a recognized composite-materials expert independently review her calculations, clearly documenting that review in the project file before finalizing the design. Is her approach ethical?",choices:["No — she should have declined the project entirely since she lacked prior experience with the method.","Yes — obtaining additional study and an independent expert review is an acceptable way to responsibly extend into an unfamiliar technical area while maintaining competence.","No — only formal continuing-education course credit, not an expert review, can establish competence.","Yes — but only if she also obtains the client's written waiver of liability for using an unfamiliar method."],answer:1,explanation:"Engineers may responsibly extend into unfamiliar areas through diligent study and qualified peer review rather than being required to refuse the work outright.",solution:"Step 1 — Identify the principle: engineers must practice within their competence, but competence can be responsibly developed and verified, not just assumed to be fixed.\nStep 2 — Apply it: she studied the method and had a recognized expert independently verify her work before finalizing it, and documented that review.\nStep 3 — Requiring outright refusal (choice A) or a liability waiver (choice D) overstates what the competence obligation demands when due diligence and expert verification are in place.\nFinal answer: Yes, this is an ethically acceptable way to responsibly extend into an unfamiliar area.",trap:"Choice A treats any unfamiliarity as disqualifying, but the codes allow engineers to responsibly grow into new technical areas through diligence and qualified review rather than mandating refusal of all unfamiliar work.",repair:"Competence can be responsibly extended through diligent study and independent expert review — it doesn't always require declining unfamiliar work outright."}
];

// ETH-02 Professional Liability
const lessons2=[
{title:"Standard of care and negligence",body:"The standard of care is the level of skill and diligence a reasonably prudent engineer in the same discipline and locality would exercise under similar circumstances — it is a reasonableness standard, not a guarantee of a perfect or error-free outcome. Professional negligence requires two elements: a breach of that standard of care, and proof that the breach proximately caused the resulting damages. An error that breaches the standard but did not cause the harm does not, by itself, establish negligence liability for that harm."},
{title:"Licensure and the PE seal",body:"Offering engineering services to the public and sealing documents generally requires an active professional license in the relevant discipline; a seal certifies that the sealing engineer personally prepared the work or exercised direct supervisory control and review over it. Practicing or sealing outside one's licensed discipline exposes the engineer to legal liability, criminal penalties, and licensure-board discipline. Many jurisdictions provide an 'industrial exemption' for engineers working solely as employees on their own employer's products, but this exemption evaporates once work is offered to the public or a seal is required for external submission."},
{title:"Contracts, indemnification, and liability limits",body:"Engineering service contracts commonly include indemnification clauses, limitation-of-liability clauses, and requirements for errors-and-omissions (E&O) insurance. These allocate financial risk between the parties, but they do not lower or excuse an engineer's underlying professional and ethical duty of care. Statutes of limitations (running from discovery of harm) and statutes of repose (running from a fixed event, such as substantial completion, regardless of discovery) set time limits on bringing a claim, but neither excuses a breach of the standard of care that occurred within those limits."},
{title:"Reporting violations and protecting the public",body:"When an engineer becomes aware that continuing work violates a code or standard, or poses an unreasonable risk, the professional obligation is to report the concern — first through internal/employer channels, then to the client or owner, and then to the appropriate public authority (building official, licensing board, regulatory agency) if the risk is not corrected. This duty can require action even when it creates friction with an employer, and many jurisdictions provide legal protections for engineers who report safety concerns in good faith through proper channels."}
];

const flashcards2=[
{front:"Standard of care",back:"The care and skill a reasonably prudent engineer in the same field would exercise under similar circumstances",note:"Being wrong isn't automatically negligent — falling below this reasonable standard is."},
{front:"Negligence",back:"A breach of the standard of care that proximately causes damages",note:"Requires both a breach AND resulting harm caused by that breach."},
{front:"PE seal requirement",back:"Required to offer engineering services to the public and to certify documents within your licensed discipline",note:"Practicing/sealing outside your license or discipline is a licensure violation."},
{front:"Industrial exemption",back:"Some jurisdictions exempt engineers working solely on their own employer's products from licensure",note:"Does not apply once work is offered to the public or requires a seal for external submission."},
{front:"Indemnification/liability clauses",back:"Contract terms allocating financial risk between parties",note:"They shift who pays for a loss — they do not lower the required standard of care."},
{front:"Statute of limitations vs. repose",back:"Limitations runs from discovery of harm; repose runs from a fixed event (e.g., substantial completion) regardless of discovery",note:"Repose can bar a claim even before the harm is discovered."},
{front:"Whistleblowing sequence",back:"Report internally first, then to the client/owner, then to the appropriate public authority if unresolved",note:"Escalate proportionally to the severity and immediacy of the risk."}
];

const questions2:Question[]=[
{id:"ETH02-Q01",skill:"Standard of care",difficulty:"Easy",prompt:"What best describes the 'standard of care' used to judge whether an engineer was professionally negligent?",choices:["Whether the engineer's design turned out to be completely free of any errors.","Whether the engineer exercised the level of skill and care that a reasonably prudent engineer in the same discipline would exercise under similar circumstances.","Whether the engineer followed every suggestion made by the client.","Whether the engineer's fee was reasonable compared to competitors."],answer:1,explanation:"The standard of care is a reasonableness standard, not a perfection standard.",solution:"Step 1 — Identify the principle: negligence is judged against the standard of care — the skill and diligence a reasonably prudent engineer in the same field would exercise under similar circumstances.\nStep 2 — Apply it: this explicitly is not a requirement of a flawless, error-free outcome.\nStep 3 — Following every client suggestion (choice C) or fee comparisons (choice D) are unrelated to the professional standard of care.\nFinal answer: The reasonably-prudent-engineer standard, not a perfection standard.",trap:"Choice A treats any error as automatic negligence, but the standard of care is a reasonableness test — even careful, competent engineers can encounter unforeseeable conditions without being negligent.",repair:"Negligence is measured against reasonable professional care, not against a standard of perfection."},
{id:"ETH02-Q02",skill:"Licensure",difficulty:"Easy",prompt:"A recent engineering graduate who has passed the FE exam but does not hold a PE license is asked by a small business owner to independently design and stamp drawings for a public building addition. What should the graduate do?",choices:["Design and seal the drawings, since passing the FE exam demonstrates sufficient competence.","Decline to seal the drawings — an unlicensed engineer cannot legally offer engineering services directly to the public or apply a PE seal.","Seal the drawings under the industrial exemption, since it is a small project.","Have a friend who is a PE in an unrelated discipline seal the drawings as a favor."],answer:1,explanation:"Only a licensed PE may offer services directly to the public and apply a seal; the FE exam alone does not confer that authority.",solution:"Step 1 — Identify the principle: offering engineering services directly to the public and applying a PE seal requires an active professional license.\nStep 2 — Apply it: passing the FE exam is a step toward licensure, but is not itself a license to practice independently or seal documents.\nStep 3 — The industrial exemption (choice C) applies to in-house work on an employer's own products, not to independently offering design services to an outside client.\nFinal answer: Decline to seal; an unlicensed engineer cannot offer these services to the public.",trap:"Choice C misapplies the industrial exemption — that exemption covers engineers working solely on their own employer's internal products, not someone independently contracting to design and stamp drawings for an outside client.",repair:"Only a licensed PE may offer engineering services directly to the public and apply a seal — passing the FE exam alone does not confer that authority."},
{id:"ETH02-Q03",skill:"Contracts and liability",difficulty:"Medium",prompt:"A design firm's contract with a client includes a clause limiting the firm's liability to the amount of its fee on the project. During construction, a design error attributable to the firm's negligence causes a costly failure. What effect does the liability-limitation clause have on the firm's professional and ethical duty of care?",choices:["It eliminates the firm's ethical duty of care entirely, since the contract defines the relationship.","It may limit the firm's financial exposure per the contract terms, but it does not excuse the underlying negligent breach of the professional standard of care.","It transfers ethical responsibility for the error to the client, who agreed to the clause.","It automatically voids the client's ability to bring any claim against the firm."],answer:1,explanation:"Contractual liability limits address financial exposure, not the underlying professional obligation to meet the standard of care.",solution:"Step 1 — Identify the principle: contract clauses allocate financial risk between parties; they do not redefine the engineer's professional standard of care.\nStep 2 — Apply it: a liability cap may limit how much the firm pays, but the negligent breach itself, and the ethical obligation it violated, still occurred.\nStep 3 — The clause does not eliminate the duty of care (choice A) or shift ethical responsibility to the client (choice C).\nFinal answer: The clause may limit financial exposure but does not excuse the negligent breach of the standard of care.",trap:"Choice A treats the contract as if it can redefine professional ethical obligations — but liability-allocation clauses govern who pays for a loss, not what standard of care was ethically required.",repair:"Liability-limiting contract clauses reallocate financial risk; they do not lower or eliminate the underlying professional standard of care."},
{id:"ETH02-Q04",skill:"Licensure",difficulty:"Medium",prompt:"An engineer employed by a manufacturer designs an internal component used solely in the company's own consumer product line and never offers services to outside clients. Does this engineer generally need to be individually licensed to perform this specific work?",choices:["Yes — all engineering design work of any kind requires an individual PE license.","In many jurisdictions, no — this typically falls under the industrial/manufacturing exemption for engineers working exclusively on their own employer's products.","No — consumer products are never subject to any licensing-board oversight.","Yes, but only if the product is later sold outside the engineer's home state."],answer:1,explanation:"Many jurisdictions provide an industrial exemption for in-house engineers who work solely on their own employer's products and don't offer services to the public.",solution:"Step 1 — Identify the principle: licensure is generally required to offer engineering services to the public; many jurisdictions carve out an industrial exemption for internal work on an employer's own products.\nStep 2 — Apply it: this engineer works exclusively in-house on the company's own product line and does not offer outside services or seal documents for external submission.\nStep 3 — Choice A overstates the licensure requirement by ignoring this common, well-established exemption.\nFinal answer: In many jurisdictions, no — this typically falls under the industrial exemption.",trap:"Choice A applies licensure requirements too broadly — the industrial exemption specifically exists for exactly this kind of purely internal, employer-product design work.",repair:"The industrial exemption generally covers in-house engineers working solely on their employer's own products — but it evaporates the moment services are offered to the public or a seal is required for external submission."},
{id:"ETH02-Q05",skill:"Statutes of limitations and repose",difficulty:"Medium",prompt:"A structural failure occurs eight years after a building's substantial completion. The jurisdiction's statute of repose for construction claims is six years from substantial completion, while its statute of limitations is two years from discovery of harm. What is the effect on a potential claim against the engineer?",choices:["The claim can still proceed because it is within two years of discovery of the harm.","The claim is likely barred, because the statute of repose extinguishes the right to sue after six years from substantial completion, regardless of when the harm was discovered.","The claim can proceed indefinitely, since professional negligence claims have no time limit.","The claim is barred only if the engineer is no longer actively licensed."],answer:1,explanation:"A statute of repose sets an absolute outer deadline from a fixed event and can bar a claim even if it is still within the discovery-based limitations period.",solution:"Step 1 — Identify the principle: statute of limitations runs from discovery of harm; statute of repose runs from a fixed event (substantial completion) and sets an absolute outer bar.\nStep 2 — Apply it: eight years have passed since substantial completion, exceeding the six-year repose period, even though it may be within two years of discovery.\nStep 3 — Because repose is an absolute bar independent of discovery, it controls here and likely bars the claim.\nFinal answer: The claim is likely barred by the six-year statute of repose.",trap:"Choice A applies only the statute of limitations (discovery-based) and overlooks that the statute of repose, an independent and absolute time bar from substantial completion, has already expired.",repair:"A statute of repose sets an absolute outer deadline from a fixed event, and can bar a claim even before the statute of limitations period would otherwise expire."},
{id:"ETH02-Q06",skill:"Reporting safety concerns",difficulty:"Medium",prompt:"An engineer working on a private project discovers, partway through design, that the site's soil conditions require a different foundation approach than what her supervisor already told the client would be used, due to a genuine safety concern. The supervisor tells her not to raise it because it would embarrass the firm. What should she do?",choices:["Stay silent, since raising the issue could harm her standing with her supervisor.","Raise the safety concern through appropriate internal channels first, and escalate to the client, and if necessary the relevant authority, if it is not properly addressed.","Quietly change the foundation design herself without telling the supervisor or the client.","Wait until after construction is complete to mention the issue in a lessons-learned memo."],answer:1,explanation:"Genuine safety concerns must be raised and escalated through proper channels, not silently worked around or deferred.",solution:"Step 1 — Identify the principle: engineers must raise and appropriately escalate genuine public-safety concerns rather than suppress them for interpersonal or reputational reasons.\nStep 2 — Apply it: staying silent (choice A) or deferring until after construction (choice D) both leave a known safety risk unaddressed during the window when it matters most.\nStep 3 — Unilaterally changing the design without informing anyone (choice C) bypasses proper communication and accountability.\nFinal answer: Raise the concern internally first, escalating to the client and, if necessary, the relevant authority.",trap:"Quietly fixing it herself (choice C) might seem like the practical solution, but it bypasses proper communication with the supervisor and client and doesn't ensure the concern is actually tracked and resolved through accountable channels.",repair:"Safety concerns must be raised and escalated through proper channels, not silently worked around or deferred until after the risk has already materialized."},
{id:"ETH02-Q07",skill:"Negligence and causation",difficulty:"Hard",prompt:"An engineer's design contains an error that falls below the standard of care, but a careful investigation shows the error did not cause the resulting structural failure, which was instead caused entirely by a contractor's unrelated construction defect. Is the engineer professionally negligent with respect to that failure?",choices:["Yes — any breach of the standard of care automatically constitutes negligence regardless of causation.","No liability for negligence attaches for that failure, because negligence requires both a breach of the standard of care and that the breach proximately caused the resulting harm.","Yes — engineers and contractors are always jointly and automatically liable for any defect discovered on a project.","No — because contractors can never be held liable for their own construction defects."],answer:1,explanation:"Negligence requires proof that the breach of the standard of care caused the harm, not just that a breach occurred.",solution:"Step 1 — Identify the principle: professional negligence requires both (a) a breach of the standard of care and (b) that the breach proximately caused the resulting damages.\nStep 2 — Apply it: the design error is a breach, but the investigation shows it did not cause the failure — the contractor's unrelated defect did.\nStep 3 — Because causation is missing for this specific failure, negligence liability for that failure does not attach to the engineer's error, even though the error itself was a deviation from the standard of care.\nFinal answer: No liability attaches for that failure, because causation is missing.",trap:"Choice A collapses 'breach' and 'negligence' into the same thing, but negligence liability specifically requires that the breach caused the harm — a breach that turns out to be harmless (as to this failure) doesn't establish liability for that failure.",repair:"Negligence requires both a breach of the standard of care AND proof that the breach caused the harm — a breach alone is not enough."},
{id:"ETH02-Q08",skill:"Sealing and liability",difficulty:"Hard",prompt:"A licensed PE allows an unlicensed engineer to independently produce and submit stamped construction documents to a building department under the PE's seal, without the PE ever reviewing that specific project. A serious design flaw is later discovered. What professional liability issue does this best illustrate?",choices:["No liability issue, because the unlicensed engineer is solely responsible for their own work product.","This illustrates 'plan-stamping' — the PE bears professional and legal responsibility for sealing work without exercising the required review/supervision, regardless of who actually made the error.","No liability issue, since the building department, not the engineer, approved the permit.","This is a licensing violation only if the unlicensed engineer was paid less than the PE."],answer:1,explanation:"A PE's seal certifies personal review and responsibility; sealing unreviewed work ('plan-stamping') keeps liability with the sealing PE.",solution:"Step 1 — Identify the principle: a PE seal certifies that the sealing engineer personally prepared the work or exercised direct supervisory control and review over it.\nStep 2 — Apply it: here the PE sealed work she never reviewed at all — this is the classic 'plan-stamping' violation.\nStep 3 — Because the seal is her personal certification, responsibility does not shift entirely to the unlicensed engineer (choice A) or to the permitting authority (choice C).\nFinal answer: This illustrates plan-stamping, and the PE retains professional/legal responsibility for the sealed work.",trap:"Choice A assumes responsibility follows whoever actually made the error, but the seal is a personal certification by the PE — she cannot outsource that legal and ethical responsibility by failing to review the work she stamped.",repair:"A PE's seal carries personal legal and professional responsibility that cannot be outsourced by sealing unreviewed work — 'plan-stamping' is a serious liability exposure, not a shortcut."},
{id:"ETH02-Q09",skill:"Certification integrity",difficulty:"Hard",prompt:"An engineer is asked by her employer to certify that installed equipment meets a specific code requirement, but her inspection reveals it does not fully comply, though the noncompliance seems minor. The employer wants her to certify compliance anyway to close out the project on schedule. What is the professionally and ethically correct action?",choices:["Certify compliance, since the noncompliance seems minor and unlikely to cause harm.","Certify compliance only if the employer indemnifies her in writing against any future claims.","Refuse to certify compliance and report the actual condition, since a certification must accurately reflect what was found regardless of scheduling pressure.","Certify compliance, but keep a private note in her personal files describing the actual condition."],answer:2,explanation:"A certification is a formal professional representation and must accurately state the actual condition found.",solution:"Step 1 — Identify the principle: a professional certification is a formal representation of fact that the engineer personally attests to; it must be accurate.\nStep 2 — Apply it: the inspection found actual noncompliance, however minor it may seem, so certifying compliance would misstate the true condition.\nStep 3 — An indemnification agreement (choice B) or a private personal note (choice D) do not change the fact that a false certification would still be submitted.\nFinal answer: Refuse to certify compliance and report the actual condition found.",trap:"Keeping a private note (choice D) might feel like a way to protect herself while still accommodating the employer, but it does not fix the core problem — an inaccurate official certification is still being submitted to those relying on it.",repair:"A certification must state the true condition found — private documentation of a known problem does not excuse submitting an inaccurate official certification."},
{id:"ETH02-Q10",skill:"Insurance and duty of care",difficulty:"Medium",prompt:"Which best describes why maintaining errors-and-omissions (E&O) insurance is a common professional-liability practice for engineering firms, but is not itself an ethical substitute for exercising due care?",choices:["E&O insurance guarantees that no client will ever file a claim against the firm.","E&O insurance helps cover the financial cost of claims arising from alleged negligence, but it does not reduce the engineer's underlying professional obligation to meet the standard of care.","E&O insurance legally exempts the firm from licensing-board discipline for any errors.","E&O insurance is required only for engineers who work exclusively on government projects."],answer:1,explanation:"Insurance manages financial risk from claims; it has no effect on the underlying duty of care or on separate licensing-board discipline.",solution:"Step 1 — Identify the principle: E&O insurance is a financial risk-management tool that helps cover the cost of defending and paying claims.\nStep 2 — Apply it: it does not change what standard of care was ethically and professionally required at the time the work was performed.\nStep 3 — It also has no bearing on a licensing board's separate authority to investigate and discipline ethical or competence violations (choice C).\nFinal answer: E&O insurance covers financial exposure from claims; it does not lower the duty of care or affect licensing-board discipline.",trap:"Choice C conflates financial insurance coverage with regulatory/licensing consequences — E&O insurance addresses civil claims, but it has no effect on a licensing board's independent disciplinary authority.",repair:"Insurance manages financial exposure from claims — it does not replace the duty of care and has no effect on separate licensing-board discipline."}
];

// ETH-03 Public Safety and Responsibility
const lessons3=[
{title:"Duty to report unsafe conditions",body:"When an engineer identifies a condition that poses a significant risk to public safety, health, or welfare, the ethical duty is to report it — first to the responsible party (employer, client, or contractor) with an opportunity to correct it, and then to the appropriate public authority (building official, licensing board, regulatory agency) if the condition is not corrected and the risk remains. Silence is not a neutral option once a genuine safety risk has been identified, and the observed hazard does not need to fall within the engineer's contracted scope of work to trigger this duty."},
{title:"Employer loyalty vs. the paramount duty to the public",body:"Engineers owe loyalty and reasonable confidentiality to their employers, but this loyalty is explicitly subordinate to the fundamental canon of holding paramount the safety, health, and welfare of the public. An employer's business interest, schedule pressure, or preference for silence does not relieve an engineer of the duty to disclose a known safety hazard through appropriate channels, and this obligation extends to protecting employees and other affected parties, not only the general public at large."},
{title:"Sustainability and environmental responsibility",body:"Modern codes of ethics recognize that 'welfare of the public' includes responsible stewardship of the environment; engineers are expected to consider sustainable-development principles and to weigh environmental, social, and economic factors in their designs. Meeting the minimum legal or regulatory limit is a floor, not a ceiling — when an engineer becomes aware of a meaningful environmental or public-health impact beyond bare legal compliance, the ethical duty to public welfare can call for disclosure and consideration of feasible alternatives."},
{title:"Informed consent and public risk communication",body:"When engineering decisions carry risk to the public or specific stakeholders, engineers have a responsibility to communicate that risk clearly, honestly, and in a way that supports informed decision-making by those affected or by the authorities who represent them. Once decision-makers are fully and honestly informed of a disclosed risk tradeoff and the chosen option still meets all applicable safety standards, an engineer is not ethically obligated to refuse to proceed simply because a more conservative, non-mandatory option existed."}
];

const flashcards3=[
{front:"Duty to report unsafe conditions",back:"Report significant public-safety risks first to the responsible party, then to the appropriate authority if uncorrected",note:"Silence after identifying a genuine hazard is itself an ethics violation."},
{front:"Employer loyalty vs. public safety",back:"Loyalty to an employer is always subordinate to the paramount duty to public safety, health, and welfare",note:"Business/schedule pressure never justifies concealing a known hazard."},
{front:"Environmental stewardship",back:"Public welfare includes environmental stewardship; engineers should weigh sustainable-development principles",note:"Legal compliance is a floor, not a ceiling, for the welfare obligation."},
{front:"Informed consent",back:"Communicate risks to the public/affected stakeholders clearly and honestly to support informed decisions",note:"Minimizing or omitting known risk to avoid conflict is a violation, not a courtesy."},
{front:"Escalation of safety concerns",back:"Internal report, then client/owner, then public authority/licensing board, scaled to the severity and immediacy of risk",note:"More severe or imminent risk justifies faster, higher escalation."},
{front:"Confidentiality limits",back:"Confidentiality obligations do not extend to concealing information necessary to protect public safety",note:"Confidentiality is not a shield for hiding safety-critical facts."},
{front:"Good-faith reporting protections",back:"Many jurisdictions protect engineers who report safety violations in good faith through proper channels",note:"Proper channels and good faith matter — protections aren't unconditional."}
];

const questions3:Question[]=[
{id:"ETH03-Q01",skill:"Duty to report",difficulty:"Easy",prompt:"While inspecting an existing structure for an unrelated renovation project, an engineer notices a severe structural crack that appears to pose an immediate collapse risk, unrelated to her contracted scope of work. What should she do?",choices:["Ignore it, since it is outside her contracted scope of work.","Note it privately in her files for possible future reference, but say nothing since it isn't her project.","Immediately notify the building owner/responsible party of the observed hazard, and notify the appropriate public authority if it is not promptly addressed given the severity of the risk.","Wait until her renovation project report is due and mention it as a minor footnote."],answer:2,explanation:"An observed severe safety hazard must be reported promptly regardless of whether it falls within the engineer's contracted scope of work.",solution:"Step 1 — Identify the principle: the paramount duty to public safety exists independent of contractual scope-of-work boundaries.\nStep 2 — Apply it: an apparent imminent collapse risk demands prompt notification to the responsible party, not silence or delay.\nStep 3 — Waiting for a routine report (choice D) or staying silent (choices A/B) leaves an urgent hazard unaddressed for an unacceptable period.\nFinal answer: Immediately notify the responsible party, escalating to authorities if unaddressed.",trap:"Treating the hazard as 'outside scope' (choice A) confuses contractual billing boundaries with the ethical duty to report an observed public-safety hazard — the two are not the same thing.",repair:"An observed severe safety hazard must be reported regardless of whether it falls within your contracted scope of work."},
{id:"ETH03-Q02",skill:"Employer loyalty vs. public safety",difficulty:"Easy",prompt:"An engineer discovers during a routine site visit that a fire suppression system was installed without a required interlock, creating a genuine safety gap. Her supervisor tells her to leave it out of the report because the client 'doesn't want to hear about it.' What should she do?",choices:["Omit it from the report as instructed, since the supervisor is her direct authority.","Include the finding accurately in her report and ensure the client and responsible parties are informed, since an employer's preference cannot justify concealing a known safety-related deficiency.","Mention it verbally to a coworker, but leave it out of the written report.","Include it in the report only if the client specifically asks about the fire suppression system."],answer:1,explanation:"A known safety deficiency must be documented and communicated to the responsible parties; an employer's preference to omit it does not override this duty.",solution:"Step 1 — Identify the principle: loyalty/deference to an employer's preference is subordinate to the paramount duty to public safety.\nStep 2 — Apply it: the missing interlock is a genuine, known safety gap that responsible parties need to know about to correct it.\nStep 3 — An informal verbal mention to a coworker (choice C) does not ensure the people responsible for fixing it are actually informed through the formal record.\nFinal answer: Include the finding accurately in the report and inform the client/responsible parties.",trap:"A verbal, informal mention to a coworker (choice C) can feel like 'raising it,' but it does not fulfill the duty to formally document and communicate a known safety deficiency to those who can act on it.",repair:"A known safety deficiency must be documented and communicated to those responsible for correcting it — informal or partial disclosure does not satisfy the reporting duty."},
{id:"ETH03-Q03",skill:"Documenting known risk",difficulty:"Medium",prompt:"A project manager pressures an engineer to remove a documented safety recommendation from a report because it might expose the firm to liability if something later goes wrong, even though the underlying risk is real. What is the correct response?",choices:["Remove the recommendation, since a documented recommendation could be used against the firm in future litigation.","Keep the safety recommendation in the report; accurately documenting known risks and appropriate mitigations is an ethical obligation that outweighs the firm's litigation-exposure concerns.","Move the recommendation into an informal email instead of the official report, so it is less discoverable.","Remove it from the report, but mention it to the client verbally and privately instead."],answer:1,explanation:"Known, real safety risks and their recommended mitigations must be documented in the formal record, not removed to reduce litigation exposure.",solution:"Step 1 — Identify the principle: accurately documenting known safety risks is an ethical obligation tied to protecting public welfare, and it is not subordinate to a firm's litigation-avoidance interest.\nStep 2 — Apply it: the risk is real, so removing or hiding the recommendation would suppress safety-relevant information from those who rely on the report.\nStep 3 — Diluting the disclosure into an informal email (choice C) or a private verbal aside (choice D) reduces its reliability and reach compared to the formal documented record.\nFinal answer: Keep the safety recommendation in the formal report.",trap:"A private verbal mention to the client (choice D) may feel like a compromise, but it is not equivalent to a documented, enforceable recommendation, and it leaves the client and any future users of the report without a durable, reliable record of the known risk.",repair:"Known safety risks must be documented in the formal record, not diluted into informal, undocumented conversations to reduce discoverability."},
{id:"ETH03-Q04",skill:"Environmental responsibility",difficulty:"Medium",prompt:"An engineer designing a manufacturing process finds that a cost-effective option would produce a byproduct that, while below current regulatory discharge limits, is understood in current scientific literature to have a meaningful long-term environmental and public-health impact. There is no legal violation involved. What does the ethical duty to protect public welfare suggest here?",choices:["No further action is needed, since the option is fully within current regulatory limits.","Proceed with the cheapest compliant option, since environmental judgment calls fall outside engineering's ethical scope.","Disclose the known impact to the client/decision-makers and present feasible lower-impact alternatives, since public welfare — including environmental stewardship — is part of the engineer's ethical responsibility even when a choice is technically legal.","Unilaterally redesign the process without informing the client, to avoid a difficult conversation."],answer:2,explanation:"Public welfare, including environmental stewardship, is part of engineering ethics and can call for action beyond bare legal compliance.",solution:"Step 1 — Identify the principle: modern codes of ethics treat environmental stewardship as part of the public-welfare obligation, not a separate, optional concern.\nStep 2 — Apply it: legal compliance sets a floor, but a known meaningful long-term impact is ethically relevant information the client/decision-makers should have.\nStep 3 — Treating regulatory compliance as automatically sufficient (choice A) ignores the broader welfare obligation; redesigning unilaterally without informing the client (choice D) bypasses the client's right to be part of an informed decision.\nFinal answer: Disclose the known impact and present feasible lower-impact alternatives.",trap:"Choice A treats meeting the regulatory minimum as the complete ethical answer, but codes of ethics explicitly extend public-welfare responsibility, including environmental considerations, beyond the legal floor.",repair:"Legal compliance is a floor, not a ceiling — the ethical duty to public welfare can call for disclosure and consideration of alternatives even when an option is technically legal."},
{id:"ETH03-Q05",skill:"Informed consent",difficulty:"Medium",prompt:"A public infrastructure project involves flood-risk tradeoffs the design team understands well, but the community meeting materials present the design in optimistic terms without clearly conveying the residual flood risk that remains after construction. What ethical principle does this best violate?",choices:["No violation, since the design meets all applicable code requirements.","A violation of the responsibility to support informed public consent by clearly and honestly communicating material risk, not just meeting minimum code compliance.","No violation, because community meetings are informational only and are not a formal engineering deliverable.","A violation only if a flood actually occurs after construction."],answer:1,explanation:"Engineers must honestly communicate known material risk to support informed public decisions, independent of whether the risk later materializes.",solution:"Step 1 — Identify the principle: engineers have a responsibility to communicate known material risk clearly and honestly to support informed decisions by the public/affected stakeholders.\nStep 2 — Apply it: presenting the design in optimistic terms while omitting the known residual flood risk fails that responsibility, regardless of code compliance.\nStep 3 — The violation exists at the time of the omission — it does not depend on whether a flood later actually occurs (choice D is wrong).\nFinal answer: A violation of the duty to honestly communicate material risk to support informed public consent.",trap:"Choice D ties the violation to a future outcome, but the ethical failure is the omission of known material risk information at the time of the community meeting — the duty concerns honest disclosure, not the eventual result.",repair:"The ethical duty to inform the public about material risk exists regardless of whether the risk later materializes — the violation is in the omission itself."},
{id:"ETH03-Q06",skill:"Escalation of safety concerns",difficulty:"Medium",prompt:"An engineer at a manufacturing plant discovers a workplace safety hazard affecting employees, reports it internally, but management does nothing for months despite repeated reminders and a documented ongoing risk of serious injury. What is an appropriate next step consistent with the profession's public-welfare obligations?",choices:["Continue reporting internally indefinitely and take no further action, since public-welfare provisions only apply to the general public, not employees.","Escalate the concern to the appropriate regulatory authority (e.g., an occupational safety agency), since internal channels have been exhausted and a serious, uncorrected risk to health and safety remains.","Resign immediately without escalating the concern anywhere, to avoid personal liability.","Do nothing further, since the engineer already fulfilled the duty by reporting it once internally."],answer:1,explanation:"After exhausting internal channels on a serious, persistent, uncorrected risk, escalation to the appropriate external authority is warranted.",solution:"Step 1 — Identify the principle: the safety, health, and welfare obligations in engineering ethics are not limited only to the general public — they extend to those affected by an engineer's work, including employees exposed to a hazard.\nStep 2 — Apply it: internal reporting has been tried repeatedly over months without correction, and the risk remains serious and ongoing.\nStep 3 — At this point, continuing to rely solely on internal channels (choices A/D) or resigning silently (choice C) leaves the uncorrected risk in place.\nFinal answer: Escalate to the appropriate external regulatory authority.",trap:"Choice A incorrectly narrows the public-welfare obligation to only the 'general public,' excluding employees — but the safety/health/welfare canon is not limited that narrowly, and a persistent uncorrected serious risk to anyone warrants escalation once internal channels are exhausted.",repair:"When internal channels are exhausted and a serious safety risk remains uncorrected, escalate to the appropriate external regulatory authority rather than treating one internal report as sufficient."},
{id:"ETH03-Q07",skill:"Informed consent",difficulty:"Hard",prompt:"An engineer's design for a public water treatment upgrade is technically sound and meets all applicable standards, but she personally believes a more conservative design margin would provide meaningfully better long-term protection against a rare but severe contamination event. The client, fully informed of the disclosed risk tradeoff, chooses the standards-compliant but less conservative design. What is the ethically correct position for the engineer?",choices:["She must refuse to proceed with the project unless the client accepts her personally preferred, more conservative margin.","Because the client made a fully informed decision understanding the disclosed risk tradeoff, and the chosen design meets all applicable safety standards, it is ethically acceptable for the engineer to proceed with the client's chosen design.","She should quietly design to her own preferred margin without telling the client, since she is the technical expert.","She must report the client to the licensing board for choosing a less conservative, standards-compliant option."],answer:1,explanation:"Once the client is fully and honestly informed and the chosen design meets applicable safety standards, proceeding is ethically acceptable even if it isn't the engineer's personally preferred margin.",solution:"Step 1 — Identify the principle: the engineer's ethical duty is to ensure decisions affecting the public are informed and meet applicable safety standards, not to unilaterally impose her personally preferred, non-mandatory design choice.\nStep 2 — Apply it: the client was fully informed of the disclosed risk difference and chose a design that still meets all applicable standards.\nStep 3 — Refusing to proceed (choice A) or overriding the client's informed choice unilaterally (choice C) goes beyond what the standards-compliance and informed-consent obligations require here.\nFinal answer: It is ethically acceptable to proceed with the client's informed, standards-compliant choice.",trap:"Choice A assumes the engineer's personally preferred margin must be honored once she believes it is 'better,' but the ethical obligation is satisfied once the client is fully informed and the chosen option still meets all applicable safety standards — a personal preference for extra conservatism beyond that is not itself mandatory.",repair:"Once a client is fully and honestly informed and the chosen option meets applicable safety standards, an engineer is not obligated to refuse to proceed just because the client didn't pick the engineer's personally preferred, non-mandatory margin."},
{id:"ETH03-Q08",skill:"Escalation of safety concerns",difficulty:"Hard",prompt:"A junior engineer notices that a senior engineer's calculations for a load-bearing element appear to contain an error that could compromise safety, but the senior engineer, well-respected and experienced, dismisses her concern without fully reviewing it. The design is scheduled to be finalized in two days. What is the most appropriate course of action?",choices:["Drop the issue, since the senior engineer has far more experience and organizational authority.","Independently verify that her concern is well-founded, then formally escalate it (e.g., to the engineer of record, a quality-review process, or management) with supporting calculations before finalization, given the safety implications and time pressure.","Wait until after the design is finalized, then raise the issue afterward so as not to seem confrontational.","Quietly redo the calculation herself and swap it into the final design package without telling anyone."],answer:1,explanation:"A substantiated, safety-relevant concern should be formally escalated through proper channels before finalization, not dropped based on seniority alone.",solution:"Step 1 — Identify the principle: the paramount duty to public safety applies regardless of organizational hierarchy, and genuine safety-relevant concerns warrant escalation.\nStep 2 — Apply it: dropping the issue (choice A) based purely on seniority does not resolve whether the underlying safety concern is valid.\nStep 3 — Waiting until after finalization (choice C) removes the opportunity to correct the issue before it matters most; silently substituting her own answer (choice D) bypasses accountability and proper review.\nStep 4 — The appropriate path is independent verification followed by formal escalation before the design is finalized.\nFinal answer: Verify the concern, then formally escalate it before finalization.",trap:"Deferring to the senior engineer's authority (choice A) is a natural instinct in a hierarchical workplace, but the paramount duty to public safety does not yield to seniority — a genuine, substantiated safety concern must still be pursued through proper escalation.",repair:"A genuine safety-relevant concern should be substantiated and escalated through proper channels, not dropped merely because a more senior colleague dismisses it, especially under time pressure before finalization."},
{id:"ETH03-Q09",skill:"Environmental responsibility",difficulty:"Hard",prompt:"A company plans to decommission an aging industrial facility and disclose only the legally mandated minimum environmental site information to the surrounding community, even though the engineering team is aware of additional, non-mandated information that would materially help residents understand potential exposure risks during demolition. What best reflects the engineer's ethical responsibility here?",choices:["Providing exactly the legally mandated minimum fully satisfies the engineer's ethical responsibility, since no law is being broken.","The engineer should advocate, within the team and to the company, for sharing the additional material risk information relevant to residents' understanding and informed decision-making, since ethical responsibility for public welfare and honest risk communication can extend beyond bare legal minimums.","The engineer has no role in this decision, since it is a corporate communications matter, not an engineering matter.","The engineer should leak the additional information anonymously to the media instead of raising it internally first."],answer:1,explanation:"Legal minimum disclosure and the ethical duty to support informed public understanding of material risk are related but not identical; the ethical duty can call for more.",solution:"Step 1 — Identify the principle: honest risk communication and support for informed public consent is part of the engineer's ethical responsibility for public welfare, distinct from bare legal compliance.\nStep 2 — Apply it: the team knows of additional material information relevant to residents' understanding of exposure risk during demolition.\nStep 3 — Treating legal minimum disclosure as automatically sufficient (choice A) or treating this as purely a communications matter outside engineering's ethical scope (choice C) both understate the engineer's responsibility here.\nStep 4 — The appropriate action is to advocate internally for sharing the additional material risk information.\nFinal answer: Advocate for disclosing the additional material risk information to support informed public understanding.",trap:"Choice A equates 'legally sufficient' with 'ethically sufficient,' but the engineer's ethical duty to support informed public understanding of material risk is a distinct, and here broader, standard than the bare legal minimum.",repair:"Legally mandated minimum disclosure and the ethical duty of honest risk communication to the public are related but not the same thing — the ethical duty can call for more."},
{id:"ETH03-Q10",skill:"Confidentiality vs. public safety",difficulty:"Medium",prompt:"Which best summarizes the correct relationship between an engineer's duty of confidentiality to an employer/client and the duty to protect public safety?",choices:["Confidentiality is absolute and always takes precedence over any other professional obligation.","Confidentiality obligations do not extend to concealing information that is necessary to protect the public from a known, significant safety risk.","Confidentiality can be broken at any time for any reason the engineer personally judges important.","Confidentiality only applies to financial information, never to technical or safety information."],answer:1,explanation:"Confidentiality yields specifically when concealment would hide information necessary to protect the public from a known significant safety risk.",solution:"Step 1 — Identify the principle: confidentiality is a real professional obligation, but it is bounded by the paramount duty to protect public safety.\nStep 2 — Apply it: the narrow, defined exception is information necessary to protect the public from a known, significant risk — not a general license to disclose freely.\nStep 3 — Treating confidentiality as absolute (choice A) or as breakable for any personally judged reason (choice C) both misstate the actual, narrowly bounded relationship.\nFinal answer: Confidentiality does not extend to concealing information necessary to protect the public from a known significant safety risk.",trap:"Choice C overcorrects into treating confidentiality as freely breakable whenever the engineer personally thinks it's important, but the actual exception is narrowly tied specifically to protecting public safety from a known significant risk, not a general override.",repair:"Confidentiality yields specifically to the need to protect public safety from a known significant risk — it is not a blanket exception for any information an engineer personally finds important."}
];

